#[test]
#[ignore = "set C1_STREAM_DIR to legally local extracted retail streams"]
fn slippery_climb_exact_uninterrupted_campaign_phase_reaches_authored_end_warp() {
    let root = PathBuf::from(
        std::env::var_os("C1_STREAM_DIR")
            .expect("C1_STREAM_DIR must name legally local extracted retail streams"),
    );
    let completion = CampaignPair::parse(&root, LevelId::LEVEL_COMPLETE);
    let title = CampaignPair::parse(&root, LevelId::TITLE);
    let generator_room = CampaignPair::parse(&root, LevelId::new_const(0x05));
    let toxic_waste = CampaignPair::parse(&root, LevelId::new_const(0x07));
    let pinstripe = CampaignPair::parse(&root, LevelId::new_const(0x08));
    let high_road = CampaignPair::parse(&root, LevelId::new_const(0x16));
    let slippery_climb = CampaignPair::parse(&root, LevelId::new_const(0x2e));

    // Start from the exact process and physical-pad phase exported by the
    // uninterrupted campaign at Generator Room. Keeping every authored
    // completion/map handoff alive from here is the shortest focused fixture
    // that derives Slippery Climb's real no-reset entry phase.
    let mut title_runtime = RetailRuntime::new_for_level(GLOBAL_WORDS, LevelId::TITLE);
    for (index, value) in [
        (GAME_STATE_GLOBAL, 0),
        (TITLE_STATE_GLOBAL, 15),
        (SAVED_TITLE_STATE_GLOBAL, 15),
        (CURRENT_MAP_LEVEL_GLOBAL, 20),
        (LEVEL_COUNT_GLOBAL, 4),
        (LEVELS_UNLOCKED_GLOBAL, 20),
        (ISLAND_CAMERA_STATE_GLOBAL, 1),
    ] {
        title_runtime
            .set_global_word(index, value)
            .expect("exact pre-Generator campaign global must exist");
    }
    let mut generator_carry = title_runtime.export_session_carry();
    generator_carry.random_seed = UNINTERRUPTED_POST_CORTEX_GENERATOR_RANDOM_SEED;
    generator_carry.draw_count = UNINTERRUPTED_POST_CORTEX_GENERATOR_DRAW_COUNT;
    generator_carry.set_random_seed_b(UNINTERRUPTED_POST_CORTEX_GENERATOR_RANDOM_SEED_B);
    let mut pad = PersistentPadState {
        snapshot: RetailPadSnapshot {
            tapped: PAD_CROSS,
            held: PAD_CROSS,
            tapped_previous: 0,
            held_previous: 0,
            held_previous_2: 0,
        },
        recovery: BrowserReplayRecoveryCounters::default(),
    };

    let (generator_survey, generator_runtime) = generator_room.run_carried_with_pad(
        generator_carry,
        SurveyInputProfile::GeneratorRoomCompletionRoute,
        5_500,
        &mut pad,
    );
    let generator_summary = generator_survey.summary();
    assert_eq!(
        generator_survey.next_lid,
        Some((
            generator_survey.frames,
            i32::try_from(LevelId::LEVEL_COMPLETE.get()).unwrap()
        )),
        "{generator_summary}"
    );
    assert_no_campaign_recovery(&generator_survey, generator_room.name);
    assert!(generator_survey.is_clean(), "{generator_summary}");
    let generator_completion = generator_room.finish_checked_with_replay(
        generator_runtime,
        LevelId::LEVEL_COMPLETE,
        &generator_survey,
    );
    let post_generator_title = carry_completion_to_title_with_pad(
        &completion,
        generator_completion,
        [0x300, 15, 15, 20, 4, 21, 0],
        &mut pad,
    );

    let toxic_carry = carry_map_to_next_level_with_pad(
        &title,
        post_generator_title,
        toxic_waste.level,
        [0, 15, 15, 21, 4, 21, 1],
        &mut pad,
    );
    let (toxic_survey, toxic_runtime) = toxic_waste.run_carried_with_pad(
        toxic_carry,
        SurveyInputProfile::ToxicWasteCompletionRoute,
        3_000,
        &mut pad,
    );
    let toxic_summary = toxic_survey.summary();
    assert_eq!(
        toxic_survey.next_lid,
        Some((
            toxic_survey.frames,
            i32::try_from(LevelId::LEVEL_COMPLETE.get()).unwrap()
        )),
        "{toxic_summary}"
    );
    assert_no_campaign_recovery(&toxic_survey, toxic_waste.name);
    assert!(toxic_survey.is_clean(), "{toxic_summary}");
    let toxic_completion = toxic_waste.finish_checked_with_replay(
        toxic_runtime,
        LevelId::LEVEL_COMPLETE,
        &toxic_survey,
    );
    let post_toxic_title = carry_completion_to_title_with_pad(
        &completion,
        toxic_completion,
        [0x300, 15, 15, 21, 4, 22, 0],
        &mut pad,
    );

    let pinstripe_carry = carry_map_to_next_level_with_pad(
        &title,
        post_toxic_title,
        pinstripe.level,
        [0, 15, 15, 22, 4, 22, 1],
        &mut pad,
    );
    let (pinstripe_survey, pinstripe_runtime) = pinstripe.run_carried_with_pad(
        pinstripe_carry,
        SurveyInputProfile::PinstripeCompletionRoute,
        2_200,
        &mut pad,
    );
    let pinstripe_summary = pinstripe_survey.summary();
    assert_eq!(
        pinstripe_survey.next_lid,
        Some((
            pinstripe_survey.frames,
            i32::try_from(LevelId::TITLE.get()).unwrap()
        )),
        "{pinstripe_summary}"
    );
    assert_no_campaign_recovery(&pinstripe_survey, pinstripe.name);
    assert!(pinstripe_survey.is_clean(), "{pinstripe_summary}");
    let post_pinstripe_title =
        pinstripe.finish_checked_with_replay(pinstripe_runtime, LevelId::TITLE, &pinstripe_survey);

    let high_road_carry = carry_map_to_next_level_with_pad(
        &title,
        post_pinstripe_title,
        high_road.level,
        [0, 15, 15, 23, 4, 23, 1],
        &mut pad,
    );
    let (high_road_survey, high_road_runtime) = high_road.run_carried_with_pad(
        high_road_carry,
        SurveyInputProfile::HighRoadCompletionRoute,
        3_000,
        &mut pad,
    );
    let high_road_summary = high_road_survey.summary();
    assert_eq!(
        high_road_survey.next_lid,
        Some((
            high_road_survey.frames,
            i32::try_from(LevelId::LEVEL_COMPLETE.get()).unwrap()
        )),
        "{high_road_summary}"
    );
    assert_no_campaign_recovery(&high_road_survey, high_road.name);
    assert!(high_road_survey.is_clean(), "{high_road_summary}");
    let high_road_completion = high_road.finish_checked_with_replay(
        high_road_runtime,
        LevelId::LEVEL_COMPLETE,
        &high_road_survey,
    );
    let post_high_road_title = carry_completion_to_title_with_pad(
        &completion,
        high_road_completion,
        [0x300, 15, 15, 23, 4, 24, 0],
        &mut pad,
    );
    let slippery_carry = carry_map_to_next_level_with_pad(
        &title,
        post_high_road_title,
        slippery_climb.level,
        [0, 15, 15, 24, 4, 24, 1],
        &mut pad,
    );
    assert_eq!(
        (
            slippery_carry.random_seed,
            slippery_carry.draw_count,
            slippery_carry.random_seed_b(),
            slippery_carry.respawn_count,
            slippery_carry.death_count,
        ),
        (
            UNINTERRUPTED_POST_HIGH_ROAD_SLIPPERY_RANDOM_SEED,
            UNINTERRUPTED_POST_HIGH_ROAD_SLIPPERY_DRAW_COUNT,
            UNINTERRUPTED_POST_HIGH_ROAD_SLIPPERY_RANDOM_SEED_B,
            0,
            0,
        ),
        "the exact Generator-to-Slippery fixture must retain the uninterrupted process phase"
    );
    assert_eq!(
        [
            GAME_STATE_GLOBAL,
            TITLE_STATE_GLOBAL,
            SAVED_TITLE_STATE_GLOBAL,
            CURRENT_MAP_LEVEL_GLOBAL,
            LEVEL_COUNT_GLOBAL,
            LEVELS_UNLOCKED_GLOBAL,
            ISLAND_CAMERA_STATE_GLOBAL,
        ]
        .map(|index| slippery_carry.globals[index]),
        [0, 15, 15, 24, 4, 24, 1],
        "the exact Generator-to-Slippery fixture must retain the authored map handoff globals"
    );
    assert_eq!(
        pad.snapshot,
        RetailPadSnapshot {
            tapped: PAD_CROSS,
            held: PAD_CROSS,
            tapped_previous: 0,
            held_previous: 0,
            held_previous_2: 0,
        },
        "the exact Generator-to-Slippery fixture must retain the physical pad epoch"
    );
    let (slippery_survey, slippery_runtime) = slippery_climb.run_carried_with_pad(
        slippery_carry,
        SurveyInputProfile::SlipperyClimbCompletionRoute,
        8_000,
        &mut pad,
    );
    let slippery_summary = slippery_survey.summary();
    assert_eq!(
        slippery_survey.next_lid,
        Some((
            slippery_survey.frames,
            i32::try_from(LevelId::LEVEL_COMPLETE.get()).unwrap()
        )),
        "{slippery_summary}"
    );
    assert_no_campaign_recovery(&slippery_survey, slippery_climb.name);
    assert!(slippery_survey.is_clean(), "{slippery_summary}");
    assert_eq!(
        campaign_progression_globals(&slippery_runtime),
        [0x500, 15, 15, 24, 4, 25, 0],
        "{slippery_summary}"
    );
}

#[test]
#[ignore = "set C1_STREAM_DIR to legally local extracted retail streams"]
fn sunset_vista_cortex_tokens_round_trip_the_exact_parent_snapshot() {
    let root = PathBuf::from(
        std::env::var_os("C1_STREAM_DIR")
            .expect("C1_STREAM_DIR must name legally local extracted retail streams"),
    );
    let parent = LevelId::new_const(0x23);
    let bonus = LevelId::new_const(0x34);
    let known_name = |level| {
        KNOWN_LEVELS
            .iter()
            .find(|known| known.id == level)
            .map(|known| known.name)
            .expect("the Cortex route level is present in the retail catalog")
    };

    let (parent_nsd, parent_nsf, parent_nsf_bytes) =
        parse_local_pair(&root, parent).expect("Sunset Vista pair must parse");
    let (parent_survey, mut parent_runtime) = survey_pair_with_runtime(
        known_name(parent),
        parent,
        &parent_nsd,
        &parent_nsf,
        &parent_nsf_bytes,
        RetailRuntime::new_for_level(GLOBAL_WORDS, parent),
        LevelContextSource::FreshBoot,
        SurveyInputProfile::SunsetVistaCortexBonusRoute,
        7_500,
    )
    .expect("ordinary pad input must collect Sunset Vista's three Cortex tokens");

    assert_eq!(parent_survey.next_lid, Some((6_963, 0x34)));
    assert_eq!(
        parent_survey.terminal.as_deref(),
        Some("frame 6963 requested level transition to 0x34")
    );
    assert_eq!(parent_survey.restarts, 0, "{}", parent_survey.summary());
    assert!(parent_survey.restart_frames.is_empty());
    assert_eq!(parent_survey.effect_counts.get("save-state"), Some(&4));
    assert_eq!(parent_survey.effect_counts.get("transition"), Some(&1));
    assert!(!parent_survey.effect_counts.contains_key("load-state"));
    for (entity, flags) in [(202, 14), (175, 11), (210, 14)] {
        assert!(
            parent_survey
                .spawn_flag_samples
                .iter()
                .any(|(_, observed_entity, observed_flags)| {
                    (*observed_entity, *observed_flags) == (entity, flags)
                }),
            "Cortex token entity {entity} must complete its authored pickup handshake"
        );
    }
    let ordinary_parent_pad = PAD_UP | PAD_RIGHT | PAD_DOWN | PAD_LEFT | PAD_CROSS | PAD_SQUARE;
    assert!(
        parent_survey
            .pad_change_samples
            .iter()
            .all(|(_, held)| held & !ordinary_parent_pad == 0),
        "the parent route must use ordinary pad input only"
    );
    assert!(parent_survey.is_clean(), "{}", parent_survey.summary());
    assert_eq!(parent_runtime.global_word(60), Ok(9));
    assert_eq!(
        parent_runtime.global_word(CHECKPOINT_ID_GLOBAL),
        Ok(210 << 8)
    );
    let exact_parent_snapshot = parent_runtime
        .saved_level_state()
        .cloned()
        .expect("the third Cortex token must save Sunset Vista's complete return state");
    assert_eq!(exact_parent_snapshot.level, parent);
    assert_eq!(exact_parent_snapshot.box_count, 0x1200);
    assert_eq!(exact_parent_snapshot.player_translation, [0, 42_496, 0]);

    let parent_transition = {
        let mut host = NsfProgramHost::new(&parent_nsd, &parent_nsf, &parent_nsf_bytes);
        parent_runtime
            .finish_level_transition(
                &mut host,
                i32::try_from(bonus.get()).expect("bonus LID fits i32"),
            )
            .expect("Sunset Vista LEVEL_END must preserve the Cortex bonus target")
    };
    assert!(parent_transition.event_failures.is_empty());
    assert_eq!(parent_transition.resolved.level, bonus);
    assert!(!parent_transition.resolved.bonus_return);
    assert_eq!(
        parent_transition.carry.saved_level_state.as_ref(),
        Some(&exact_parent_snapshot)
    );

    let (bonus_nsd, bonus_nsf, bonus_nsf_bytes) =
        parse_local_pair(&root, bonus).expect("Cortex Bonus pair must parse");
    let bonus_runtime =
        RetailRuntime::new_from_session(GLOBAL_WORDS, bonus, parent_transition.carry)
            .expect("Cortex Bonus must import Sunset Vista's complete session carry");
    assert_eq!(bonus_runtime.global_word(60), Ok(9));
    assert_eq!(
        bonus_runtime.saved_level_state(),
        Some(&exact_parent_snapshot)
    );
    let (bonus_survey, mut bonus_runtime) = survey_pair_with_runtime(
        known_name(bonus),
        bonus,
        &bonus_nsd,
        &bonus_nsf,
        &bonus_nsf_bytes,
        bonus_runtime,
        LevelContextSource::SessionGlobals,
        SurveyInputProfile::CortexBonusCompletionRoute,
        900,
    )
    .expect("ordinary pad input must traverse Cortex Bonus and request its carried return");

    assert_eq!(bonus_survey.restarts, 0, "{}", bonus_survey.summary());
    assert!(bonus_survey.restart_frames.is_empty());
    assert_eq!(bonus_survey.effect_counts.get("load-state"), Some(&1));
    assert!(!bonus_survey.effect_counts.contains_key("transition"));
    assert_eq!(bonus_survey.next_lid, None);
    assert_eq!(
        bonus_survey.terminal.as_deref(),
        Some("requested cross-level restart from 0x34 to 0x23")
    );
    let ordinary_bonus_pad = PAD_LEFT | PAD_RIGHT | PAD_UP | PAD_CROSS | PAD_SQUARE;
    assert!(
        bonus_survey
            .pad_change_samples
            .iter()
            .all(|(_, held)| held & !ordinary_bonus_pad == 0),
        "the Cortex Bonus route must use ordinary pad input only"
    );
    assert!(bonus_survey.is_clean(), "{}", bonus_survey.summary());
    assert_eq!(
        bonus_runtime.saved_level_state(),
        Some(&exact_parent_snapshot),
        "the bonus LoadState handshake must retain every parent-snapshot field"
    );

    let mut bonus_host = NsfProgramHost::new(&bonus_nsd, &bonus_nsf, &bonus_nsf_bytes);
    let return_transition = bonus_runtime
        .finish_level_transition(&mut bonus_host, -2)
        .expect("Cortex Bonus LEVEL_END must resolve the carried Sunset Vista snapshot");
    assert!(return_transition.event_failures.is_empty());
    assert_eq!(return_transition.next_lid_after_event, -2);
    assert_eq!(return_transition.resolved.level, parent);
    assert!(return_transition.resolved.bonus_return);
    assert_eq!(
        return_transition.carry.saved_level_state.as_ref(),
        Some(&exact_parent_snapshot),
        "the returned carry must be exactly the snapshot saved by token 210"
    );
}

fn progression_frame_count() -> u32 {
    std::env::var("C1_PROGRESSION_FRAMES")
        .ok()
        .and_then(|value| value.parse::<u32>().ok())
        .filter(|frames| (1..=MAX_SURVEY_FRAMES).contains(frames))
        .unwrap_or(DEFAULT_PROGRESSION_FRAMES)
}

