/// Deterministic ordinary-pad route from Fumbling in the Dark's fresh spawn
/// through the authored `WarpC` exit. This captures the narrow platform and
/// final spider-bounce sequence without injecting position or runtime state.
struct FumblingInTheDarkCompletionRouteController;

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct TawnaBonusCompletionRouteController {
    jump_hold: u8,
    release_wait: u8,
    warp_tick: u16,
}

/// Ordinary-pad characterization route for Brio Bonus. Coordinates are read
/// only to choose inputs; the controller never mutates Crash or retail state.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct BrioBonusCompletionRouteController {
    jump_hold: u8,
    release_wait: u8,
    warp_tick: u16,
    opening_stage: u8,
    rolling_stones_layout: bool,
    rolling_spin_ready: bool,
    stage: u8,
    stage_tick: u16,
}

/// Deterministic ordinary-pad route through Cortex Bonus's two timed TNT
/// retreats, bridge jumps, and authored `WillC` warp. Coordinates are used
/// only to decide what a player would press; the route never mutates runtime
/// state or teleports Crash.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct CortexBonusCompletionRouteController {
    stage: u8,
    retreat_stage: u8,
    jump_hold: u8,
    release_wait: u8,
}

impl CortexBonusCompletionRouteController {
    const FIRST_RETREAT_FRAME: u32 = 200;
    const FIRST_BRIDGE_RUN_FRAME: u32 = 220;
    const SECOND_RETREAT_FRAME: u32 = 455;
    const SECOND_BRIDGE_RETURN_FRAME: u32 = 521;

    fn held(&mut self, frame: u32, player: Option<PlayerTrace>) -> u32 {
        let Some(player) = player else {
            return 0;
        };
        if player.state == 32 {
            return 0;
        }

        if self.stage == 2 && player.translation[0] >= 1_060_000 && player.status_a & 1 != 0 {
            self.stage = 3;
            self.retreat_stage = 1;
        }
        if self.retreat_stage == 1 {
            if frame >= Self::FIRST_RETREAT_FRAME
                && player.translation[0] < 800_000
                && player.state == 14
            {
                self.retreat_stage = 2;
                self.jump_hold = 13;
                return PAD_CROSS;
            }
            if frame >= Self::FIRST_RETREAT_FRAME {
                let direction = if player.translation[0] > 840_000 || player.velocity[0] > 100_000 {
                    PAD_LEFT
                } else if player.translation[0] < 780_000 || player.velocity[0] < -100_000 {
                    PAD_RIGHT
                } else {
                    0
                };
                return direction | PAD_CROSS;
            }
            return if player.translation[0] > 1_100_000 || player.velocity[0] > 100_000 {
                PAD_LEFT
            } else if player.translation[0] < 1_050_000 || player.velocity[0] < -100_000 {
                PAD_RIGHT
            } else {
                0
            };
        }
        if self.retreat_stage == 2 {
            let mut held = if frame >= Self::FIRST_BRIDGE_RUN_FRAME {
                PAD_RIGHT
            } else {
                0
            };
            if self.jump_hold > 0 {
                self.jump_hold -= 1;
                held |= PAD_CROSS;
            }
            if frame >= Self::FIRST_BRIDGE_RUN_FRAME
                && player.translation[0] >= 1_100_000
                && player.status_a & 1 != 0
            {
                self.retreat_stage = 0;
                self.stage = 4;
                self.jump_hold = 13;
                self.release_wait = 2;
                held |= PAD_CROSS;
            }
            return held;
        }
        if self.stage == 4
            && (2_200_000..2_400_000).contains(&player.translation[0])
            && player.state == 14
        {
            self.stage = 9;
            self.jump_hold = 13;
            return PAD_RIGHT | PAD_CROSS;
        }
        if self.stage == 9 {
            if player.translation[0] >= 2_600_000 && player.state == 14 {
                self.stage = 5;
            } else {
                let mut held = if player.translation[0] < 2_620_000 {
                    PAD_RIGHT
                } else if player.translation[0] > 2_700_000 || player.velocity[0] > 100_000 {
                    PAD_LEFT
                } else if player.velocity[0] < -100_000 {
                    PAD_RIGHT
                } else {
                    0
                };
                if self.jump_hold > 0 {
                    self.jump_hold -= 1;
                    held |= PAD_CROSS;
                }
                if player.translation[0] < 2_500_000 {
                    held |= PAD_SQUARE;
                }
                return held;
            }
        }
        if self.stage == 5
            && (Self::SECOND_RETREAT_FRAME.saturating_sub(5)..Self::SECOND_RETREAT_FRAME)
                .contains(&frame)
        {
            return PAD_LEFT;
        }
        if self.stage == 5 && frame >= Self::SECOND_RETREAT_FRAME && player.status_a & 1 != 0 {
            self.stage = 6;
            self.jump_hold = 3;
            self.release_wait = 2;
            return PAD_LEFT | PAD_CROSS;
        }
        if self.stage == 6 {
            if (2_400_000..2_550_000).contains(&player.translation[0]) && player.state == 14 {
                self.stage = 7;
                self.jump_hold = 13;
                return PAD_LEFT | PAD_CROSS;
            }
            let mut held = if player.translation[0] > 2_550_000 {
                PAD_LEFT
            } else if player.translation[0] < 2_430_000 || player.velocity[0] < -100_000 {
                PAD_RIGHT
            } else if player.velocity[0] > 100_000 {
                PAD_LEFT
            } else {
                0
            };
            if self.jump_hold > 0 {
                self.jump_hold -= 1;
                held |= PAD_CROSS;
            }
            return held;
        }
        if self.stage == 7 {
            if (Self::SECOND_BRIDGE_RETURN_FRAME.saturating_sub(7)
                ..Self::SECOND_BRIDGE_RETURN_FRAME)
                .contains(&frame)
            {
                return PAD_RIGHT;
            }
            if frame >= Self::SECOND_BRIDGE_RETURN_FRAME {
                self.stage = 8;
                self.jump_hold = 20;
                self.release_wait = 2;
                return PAD_RIGHT | PAD_CROSS;
            }
            let mut held = if player.translation[0] > 2_080_000 || player.velocity[0] > 100_000 {
                PAD_LEFT
            } else if player.translation[0] < 2_020_000 || player.velocity[0] < -100_000 {
                PAD_RIGHT
            } else {
                0
            };
            if self.jump_hold > 0 {
                self.jump_hold -= 1;
                held |= PAD_CROSS;
            }
            return held;
        }
        if self.stage == 8 {
            if player.translation[0] >= 2_580_000 && player.status_a & 1 != 0 && player.state != 40
            {
                self.stage = 10;
                self.jump_hold = 30;
                self.release_wait = 2;
                return PAD_RIGHT | PAD_CROSS;
            }
            let mut held = PAD_RIGHT | PAD_SQUARE;
            if self.jump_hold > 0 {
                self.jump_hold -= 1;
                held |= PAD_CROSS;
            }
            return held;
        }
        if self.stage == 10 {
            if player.translation[0] >= 4_100_000 {
                self.stage = 11;
                return 0;
            }
            let mut held = PAD_RIGHT;
            if player.translation[0] < 3_300_000 {
                held |= PAD_SQUARE;
            }
            if self.jump_hold > 0 {
                self.jump_hold -= 1;
                held |= PAD_CROSS;
            } else if self.release_wait > 0 {
                self.release_wait -= 1;
            } else if player.state != 40 && player.status_a & 1 != 0 {
                self.jump_hold = 30;
                self.release_wait = 2;
                return PAD_RIGHT | PAD_CROSS;
            }
            return held;
        }
        if self.stage == 11 {
            return PAD_UP;
        }

        if self.stage == 4 && player.translation[0] >= 2_400_000 && player.state == 14 {
            self.stage = 5;
        }
        let mut held = if self.stage == 5 {
            if player.translation[0] < 2_620_000 {
                0
            } else if player.translation[0] > 2_700_000 || player.velocity[0] > 100_000 {
                PAD_LEFT
            } else if player.velocity[0] < -100_000 {
                PAD_RIGHT
            } else {
                0
            }
        } else {
            PAD_RIGHT
        };
        if self.jump_hold > 0 {
            self.jump_hold -= 1;
            held |= PAD_CROSS;
        } else if self.release_wait > 0 {
            self.release_wait -= 1;
        } else if player.state != 40 && player.status_a & 1 != 0 {
            let takeoff = match self.stage {
                0 => {
                    self.stage = 1;
                    true
                }
                1 if player.translation[0] >= 400_000 => {
                    self.stage = 2;
                    true
                }
                3 if player.translation[0] >= 900_000 => {
                    self.stage = 4;
                    true
                }
                4 if player.translation[0] >= 1_950_000 => true,
                _ => false,
            };
            if takeoff {
                self.jump_hold = if self.stage == 4 { 3 } else { 13 };
                self.release_wait = 2;
                held |= PAD_CROSS;
            }
        }
        if self.stage >= 4 && player.translation[0] < 1_800_000 && frame % 48 < 4 {
            held |= PAD_SQUARE;
        }
        if self.stage == 2 && self.jump_hold > 0 {
            held |= PAD_SQUARE;
        }
        held
    }
}

impl TawnaBonusCompletionRouteController {
    fn held(&mut self, frame: u32, player: Option<PlayerTrace>) -> u32 {
        let Some(player) = player else {
            return 0;
        };
        if player.state == 32 {
            self.warp_tick = self.warp_tick.saturating_add(1);
            return if self.warp_tick == 300 { PAD_CROSS } else { 0 };
        }
        if player.translation[0] > 2_300_000 && player.translation[2] > -220_000 {
            return PAD_UP;
        }
        if player.translation[2] <= -220_000 && player.translation[0] > 2_570_000 {
            return PAD_LEFT;
        }

        let mut held = PAD_RIGHT;
        if self.jump_hold > 0 {
            self.jump_hold -= 1;
            held |= PAD_CROSS;
        } else if self.release_wait > 0 {
            self.release_wait -= 1;
        } else if player.state != 40 && player.status_a & 1 != 0 {
            self.jump_hold = 13;
            self.release_wait = 2;
            held |= PAD_CROSS;
        }
        if frame % 48 < 4 {
            held |= PAD_SQUARE;
        }
        held
    }
}

impl BrioBonusCompletionRouteController {
    fn held(
        &mut self,
        frame: u32,
        player: Option<PlayerTrace>,
        objects: &[ProgramObjectTrace],
    ) -> u32 {
        let Some(player) = player else {
            return 0;
        };
        if player.state == 32 {
            self.warp_tick = self.warp_tick.saturating_add(1);
            return if self.warp_tick == 300 { PAD_CROSS } else { 0 };
        }

        let first_crate_x = objects
            .iter()
            .filter(|object| object.program.name().as_deref() == Some("BoxsC"))
            .map(|object| object.translation[0])
            .min();
        self.rolling_stones_layout |= first_crate_x == Some(624_640);
        let rolling_stones_layout = self.rolling_stones_layout;
        if self.opening_stage == 0
            && player.state == 14
            && first_crate_x
                .is_some_and(|crate_x| player.translation[0].abs_diff(crate_x) < 160_000)
        {
            self.opening_stage = 1;
            self.jump_hold = 0;
            self.release_wait = 0;
        }
        if self.opening_stage == 1
            && let Some(crate_x) = first_crate_x
        {
            let predicted_x =
                player.translation[0].saturating_add(player.velocity[0].saturating_mul(3) / 34);
            let horizontal = if predicted_x > crate_x + 12_000 {
                PAD_LEFT
            } else if predicted_x < crate_x - 12_000 {
                PAD_RIGHT
            } else {
                0
            };
            if player.status_a & 1 != 0 && player.translation[0].abs_diff(crate_x) < 100_000 {
                self.opening_stage = 2;
                return 0;
            }
            return horizontal;
        }
        if self.opening_stage == 2 {
            self.opening_stage = 3;
            self.jump_hold = 20;
            self.release_wait = 2;
            return PAD_RIGHT | PAD_CROSS;
        }

        let rolling_upper_crate = objects.iter().find(|object| {
            object.program.name().as_deref() == Some("BoxsC")
                && object.translation == [2_672_640, 819_200, -25_600]
        });
        if rolling_stones_layout
            && self.stage == 0
            && player.translation[0] >= 2_400_000
            && rolling_upper_crate.is_none_or(|crate_object| crate_object.state != 26)
        {
            self.stage = 9;
            self.jump_hold = 45;
            self.release_wait = 0;
            self.rolling_spin_ready = true;
        }
        if self.stage == 7 {
            self.stage = 9;
            self.jump_hold = 45;
            return PAD_RIGHT | PAD_CROSS;
        }
        if self.stage == 8 {
            let target_x = 2_100_000;
            let predicted_x =
                player.translation[0].saturating_add(player.velocity[0].saturating_mul(3) / 34);
            if player.status_a & 1 != 0
                && player.translation[0].abs_diff(target_x) < 100_000
                && player.velocity[0].abs() <= 100_000
            {
                self.stage = 7;
                return 0;
            }
            return if predicted_x > target_x + 12_000 {
                PAD_LEFT
            } else if predicted_x < target_x - 12_000 {
                PAD_RIGHT
            } else {
                0
            };
        }
        if self.stage == 9 {
            if player.translation[0] >= 2_450_000 && player.status_a & 1 != 0 {
                // Cross is still held from the long jump over the preceding
                // gap. Release it for two samples on the metal floor so the
                // capped crate staircase receives a real jump edge.
                self.stage = 10;
                self.stage_tick = 0;
                self.rolling_spin_ready = true;
                return PAD_RIGHT;
            }
            return PAD_RIGHT | PAD_CROSS;
        }
        if self.stage == 10 {
            self.stage_tick = self.stage_tick.saturating_add(1);
            if self.stage_tick < 2 {
                return PAD_RIGHT;
            }
            self.stage = 11;
            self.jump_hold = 30;
            self.release_wait = 2;
            return PAD_RIGHT | PAD_CROSS;
        }
        if self.stage == 11 {
            if player.translation[0] >= 3_300_000 {
                self.stage = 12;
                self.jump_hold = 30;
                self.release_wait = 2;
                return PAD_RIGHT | PAD_CROSS;
            }

            let mut held = PAD_RIGHT;
            if self.jump_hold > 0 {
                self.jump_hold -= 1;
                held |= PAD_CROSS;
            } else if self.release_wait > 0 {
                self.release_wait -= 1;
            } else if player.status_a & 1 != 0 {
                self.jump_hold = 30;
                self.release_wait = 2;
                held |= PAD_CROSS;
            }
            if self.rolling_spin_ready
                && player.translation[1] > 850_000
                && player.velocity[1] > 200_000
            {
                // Spin only after the fresh jump has started. Pressing Square
                // on the floor enters the spin state before Cross can create
                // the jump that clears the first metal cap.
                self.rolling_spin_ready = false;
                held |= PAD_SQUARE;
            } else if !self.rolling_spin_ready {
                // The retail route lands on the newly exposed TNT after the
                // jumping spin. Its cap leaves an exact-height opening, so use
                // a short depth nudge to enter that opening, then center again
                // before descending onto the TNT.
                let predicted_z =
                    player.translation[2].saturating_add(player.velocity[2].saturating_mul(3) / 34);
                let target_z = 70_000;
                if predicted_z < target_z - 8_000 {
                    held |= PAD_DOWN;
                } else if predicted_z > target_z + 8_000 {
                    held |= PAD_UP;
                }
                if player.translation[0] >= 2_600_000 {
                    self.stage = 13;
                    return PAD_LEFT | PAD_UP;
                }
            }
            return held;
        }
        if self.stage == 13 {
            if rolling_upper_crate.is_some_and(|crate_object| crate_object.state != 26) {
                self.stage = 14;
                return PAD_RIGHT | PAD_CROSS;
            }

            let predicted_x =
                player.translation[0].saturating_add(player.velocity[0].saturating_mul(3) / 34);
            let predicted_z =
                player.translation[2].saturating_add(player.velocity[2].saturating_mul(3) / 34);
            let horizontal = if predicted_x > 2_650_000 {
                PAD_LEFT
            } else if predicted_x < 2_610_000 {
                PAD_RIGHT
            } else {
                0
            };
            let depth = if predicted_z > -17_000 {
                PAD_UP
            } else if predicted_z < -34_000 {
                PAD_DOWN
            } else {
                0
            };
            return horizontal | depth;
        }
        if self.stage == 14 {
            if player.translation[0] >= 2_780_000
                && player.translation[1] > 1_050_000
                && player.status_a & 1 != 0
            {
                // Re-center onto the second metal cap, release Cross for two
                // samples, then create the fresh edge used for the final gap.
                self.stage = 15;
                self.stage_tick = 0;
                return PAD_RIGHT | PAD_UP;
            }
            if player.translation[0] >= 3_300_000 {
                self.stage = 12;
                self.jump_hold = 30;
                self.release_wait = 2;
                return PAD_RIGHT | PAD_CROSS;
            }
            let mut held = PAD_RIGHT | PAD_CROSS;
            let predicted_z =
                player.translation[2].saturating_add(player.velocity[2].saturating_mul(3) / 34);
            if player.translation[0] >= 2_780_000 {
                if predicted_z > -17_000 {
                    held |= PAD_UP;
                } else if predicted_z < -34_000 {
                    held |= PAD_DOWN;
                }
            } else if predicted_z > 76_000 {
                held |= PAD_UP;
            } else if predicted_z < 58_000 {
                held |= PAD_DOWN;
            }
            return held;
        }
        if self.stage == 15 {
            self.stage_tick = self.stage_tick.saturating_add(1);
            if self.stage_tick < 2 {
                return PAD_RIGHT | PAD_UP;
            }
            self.stage = 12;
            self.jump_hold = 30;
            self.release_wait = 2;
            return PAD_RIGHT | PAD_CROSS;
        }

        let upper_crate_broken = objects.iter().any(|object| {
            object.state == 24
                && matches!(
                    object.origin,
                    ObjectOrigin::Runtime {
                        executable: 34,
                        subtype: 8,
                    }
                )
        });
        if !rolling_stones_layout && self.stage == 0 && upper_crate_broken {
            self.stage = 1;
            self.jump_hold = 0;
        }
        if self.stage == 1 {
            if player.translation[0] < 1_950_000 && player.status_a & 1 != 0 {
                if player.velocity[0] < -100_000 {
                    return PAD_RIGHT;
                }
                self.stage = 2;
                self.stage_tick = 0;
                return 0;
            }
            return PAD_LEFT;
        }
        if self.stage == 2 {
            self.stage_tick = self.stage_tick.saturating_add(1);
            if self.stage_tick > 1
                && matches!(player.state, 3 | 4 | 14)
                && player.velocity[1] > 700_000
                && player.translation[0] < 1_950_000
            {
                self.stage = 3;
                self.jump_hold = 13;
                return PAD_RIGHT;
            }
            let horizontal = if player.translation[0] > 1_890_000 {
                PAD_LEFT
            } else if player.translation[0] < 1_810_000 {
                PAD_RIGHT
            } else {
                0
            };
            return horizontal | (u32::from(self.stage_tick == 1) * PAD_CROSS);
        }
        if self.stage >= 3 && player.translation[0] > 4_000_000 && player.translation[2] > -220_000
        {
            return PAD_UP;
        }

        let mut held = PAD_RIGHT;
        if self.jump_hold > 0 {
            self.jump_hold -= 1;
            held |= PAD_CROSS;
        } else if self.release_wait > 0 {
            self.release_wait -= 1;
        } else if player.state != 40 && player.status_a & 1 != 0 {
            self.jump_hold = 30;
            self.release_wait = 2;
            held |= PAD_CROSS;
        }
        if self.opening_stage == 0 && (840_000..1_100_000).contains(&player.translation[0]) {
            held |= PAD_SQUARE;
        }
        if rolling_stones_layout && self.stage == 0 && player.translation[0] >= 2_050_000 {
            self.stage = 8;
        }
        let _ = frame;
        held
    }
}

/// Ordinary-pad completion route for Bonus 2 after The Great Gate supplies
/// the three-Tawna-token carry. The carried global 60 value selects the
/// authored full crate staircase; a fresh level boot intentionally does not.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct TawnaBonusTwoCompletionRouteController {
    jump_hold: u8,
    release_wait: u8,
    warp_tick: u16,
    stage: u8,
}

impl TawnaBonusTwoCompletionRouteController {
    fn continue_jump(&mut self, direction: u32) -> u32 {
        if self.jump_hold == 0 {
            direction
        } else {
            self.jump_hold -= 1;
            direction | PAD_CROSS
        }
    }

    fn held(&mut self, frame: u32, player: Option<PlayerTrace>) -> u32 {
        let Some(player) = player else {
            return 0;
        };
        let [x, y, _z] = player.translation;
        let grounded = player.status_a & 1 != 0;

        if player.state == 32 {
            self.warp_tick = self.warp_tick.saturating_add(1);
            return if self.warp_tick == 300 { PAD_CROSS } else { 0 };
        }

        // Release and re-press jump after the first arrow-crate launch. This
        // keeps the opening stack traversal stable without injecting motion.
        if self.stage == 0 && player.state == 14 && x < 1_000_000 {
            self.stage = 10;
            return PAD_RIGHT;
        }
        if self.stage == 10 {
            self.stage = 0;
            self.jump_hold = 13;
            return PAD_RIGHT | PAD_CROSS;
        }

        // The second arrow crate launches Crash above one isolated high
        // crate. Brake over it, then use it as the takeoff for the final bank.
        if self.stage == 0 && player.state == 14 && x > 1_700_000 {
            self.stage = 1;
        }
        if self.stage == 1 && grounded && x > 2_300_000 {
            self.stage = 2;
            self.jump_hold = 30;
            return PAD_RIGHT | PAD_CROSS;
        }
        if self.stage == 1 {
            return (if x < 2_240_000 { PAD_RIGHT } else { PAD_LEFT }) | PAD_CROSS;
        }

        // Climb the three crate tiers with two short hops, then clear the
        // final gap with a full jump.
        if self.stage == 2 && grounded && x > 2_900_000 {
            self.stage = 3;
            self.jump_hold = 1;
            return PAD_RIGHT | PAD_CROSS;
        }
        if self.stage == 3 && grounded && x > 3_100_000 && y >= 900_000 {
            self.stage = 4;
            self.jump_hold = 1;
            return PAD_RIGHT | PAD_CROSS;
        }
        if self.stage == 4 && grounded && x > 3_300_000 && y >= 1_000_000 {
            self.stage = 5;
            self.jump_hold = 30;
            return PAD_RIGHT | PAD_CROSS;
        }
        if matches!(self.stage, 2..=5) {
            if self.stage == 5 && grounded && x > 4_000_000 {
                self.stage = 6;
                self.jump_hold = 13;
                return PAD_RIGHT | PAD_UP | PAD_CROSS;
            }
            return self.continue_jump(PAD_RIGHT);
        }

        // The portal is behind the last crate bank. Jump diagonally over its
        // near lip, then center on WarpC until the normal WARP event fires.
        if self.stage == 6 {
            let horizontal = if x > 4_200_000 {
                PAD_LEFT
            } else if x < 4_120_000 {
                PAD_RIGHT
            } else {
                0
            };
            return self.continue_jump(horizontal | PAD_UP);
        }

        let mut held = PAD_RIGHT;
        if self.jump_hold > 0 {
            self.jump_hold -= 1;
            held |= PAD_CROSS;
        } else if self.release_wait > 0 {
            self.release_wait -= 1;
        } else if player.state != 40 && grounded {
            self.jump_hold = 13;
            self.release_wait = 2;
            held |= PAD_CROSS;
        }
        if ((450_000..1_200_000).contains(&x) || frame % 48 < 4)
            && !(1_400_000..2_800_000).contains(&x)
        {
            held |= PAD_SQUARE;
        }
        held
    }
}

