#[test]
#[ignore = "set C1_STREAM_DIR to legally local extracted retail streams"]
fn jungle_rollers_collects_aku_after_an_authored_death_restart() {
    let root = PathBuf::from(
        std::env::var_os("C1_STREAM_DIR")
            .expect("C1_STREAM_DIR must name legally local extracted retail streams"),
    );
    let level = LevelId::new_const(0x0c);
    let (nsd, nsf, nsf_bytes) =
        parse_local_pair(&root, level).expect("Jungle Rollers pair must parse");
    let (survey, runtime) = survey_pair_with_runtime(
        "Jungle Rollers",
        level,
        &nsd,
        &nsf,
        &nsf_bytes,
        RetailRuntime::new_for_level(GLOBAL_WORDS, level),
        LevelContextSource::FreshBoot,
        SurveyInputProfile::JungleDeathAkuCompletionRoute,
        600,
    )
    .expect("Jungle Rollers post-death mask route must execute");

    assert_eq!(survey.frames, 600);
    assert_eq!(survey.restarts, 1);
    // The native-atomic post-spawn instruction tail commits `LoadState` on
    // frame 199; frame 200 is the first frame of the restored Crash instance.
    assert_eq!(survey.restart_frames, [199]);
    assert_eq!(spawned_entity_trace(&runtime, 9), Ok(None));
    assert_eq!(survey.execution_errors, 0);
    assert_eq!(runtime.faulted_object_count(), 0);
    assert!(
        survey.is_clean(),
        "the post-death mask route must remain clean: {}",
        survey.summary()
    );

    let player = player_trace(&runtime)
        .expect("the post-death player trace must remain readable")
        .expect("Crash must remain live after collecting Aku");
    let doctor_word = runtime
        .global_word(DOCTOR_OBJECT_GLOBAL)
        .expect("the post-death Doctor global must remain readable");
    let doctor_reference = CollisionObjectReference::from_word(doctor_word)
        .expect("the post-death Doctor global must retain a checked object reference");
    let doctor_handle = runtime
        .object_for_vm(doctor_reference.object())
        .expect("the null-zone Doctor object must survive the authored restart");
    let doctors = runtime
        .render_objects()
        .expect("the post-death render snapshot must remain valid")
        .into_iter()
        .filter(|object| object.object == doctor_handle)
        .collect::<Vec<_>>();
    assert_eq!(doctors.len(), 1);
    let doctor = &doctors[0];
    assert_eq!(doctor.executable, 5);
    assert_eq!(doctor.subtype, 0);
    assert_eq!(
        doctor
            .program
            .and_then(|program| program.global_eid().name())
            .as_deref(),
        Some("DoctC")
    );
    assert!(doctor.display_eligible);
    assert_eq!(
        doctor.animation_reference.map(AnimationReference::offset),
        Some(0)
    );
    assert_eq!(
        doctor
            .texture_frame_snapshot
            .expect("Aku must retain its live display-boundary texture slots")
            .slots()
            .iter()
            .flatten()
            .count(),
        5
    );
    let doctor_vm = runtime
        .machine()
        .object(doctor_reference.object())
        .expect("the displayed Doctor must retain VM storage");
    assert_eq!(doctor_vm.state(), 1);
    assert_eq!(doctor_vm.state_flags(), 9);
    assert_eq!(
        doctor_vm
            .register(process_register::ANIMATION_SEQUENCE)
            .ok()
            .and_then(AnimationReference::from_word)
            .map(AnimationReference::offset),
        Some(0)
    );
    assert_ne!(doctor.transform.translation, player.translation);
}

#[test]
#[ignore = "set C1_STREAM_DIR to legally local extracted retail streams"]
fn jungle_rollers_death_aku_route_reaches_authored_level_complete() {
    let root = PathBuf::from(
        std::env::var_os("C1_STREAM_DIR")
            .expect("C1_STREAM_DIR must name legally local extracted retail streams"),
    );
    let level = LevelId::new_const(0x0c);
    let (nsd, nsf, nsf_bytes) =
        parse_local_pair(&root, level).expect("Jungle Rollers pair must parse");
    let (survey, mut runtime) = survey_pair_with_runtime(
        "Jungle Rollers",
        level,
        &nsd,
        &nsf,
        &nsf_bytes,
        RetailRuntime::new_for_level(GLOBAL_WORDS, level),
        LevelContextSource::FreshBoot,
        SurveyInputProfile::JungleDeathAkuCompletionRoute,
        3_600,
    )
    .expect("Jungle Rollers death/Aku completion route must execute");

    assert_eq!(survey.frames, 3_387, "{}", survey.summary());
    assert_eq!(
        survey.terminal.as_deref(),
        Some("frame 3387 requested level transition to 0x2d")
    );
    assert_eq!(
        survey.next_lid,
        Some((3_387, i32::try_from(LevelId::LEVEL_COMPLETE.get()).unwrap()))
    );
    assert_eq!(survey.zone_transitions, 31);
    assert_eq!(survey.restarts, 1);
    // Match the restart boundary above: frame 200 is already the restored
    // instance's first cooperative update.
    assert_eq!(survey.restart_frames, [199]);
    let (fall_frame, fall) = survey
        .first_terminal_fall
        .as_ref()
        .expect("holding forward must enter the authored opening terminal fall");
    assert_eq!(*fall_frame, 189);
    assert_eq!(
        fall.zone,
        Eid::from_name("0c_cZ").expect("fixed Jungle fall-zone EID is valid")
    );
    assert_eq!(fall.state, 22);
    assert_eq!(
        survey.checkpoint_samples,
        [
            (1, -1, [0, 0, 0]),
            (1_903, 46 << 8, [-563_968, 2_236_928, 15_717_376]),
        ]
    );
    assert_eq!(
        survey.box_count_samples,
        [
            (1, 0),
            (268, 0x100),
            (269, 0x200),
            (1_173, 0x300),
            (1_174, 0x400),
            (1_903, 0x500),
            (1_934, 0x600),
            (1_935, 0x700),
            (1_938, 0x800),
            (1_939, 0x900),
            (1_940, 0xa00),
            (1_948, 0xb00),
            (1_954, 0xc00),
        ]
    );
    assert_eq!(survey.saved_box_count_samples, [(1_903, 0x400)]);
    assert_eq!(survey.effect_counts.get("load-state").copied(), Some(1));
    assert_eq!(survey.effect_counts.get("save-state").copied(), Some(1));
    assert_eq!(survey.effect_counts.get("transition").copied(), Some(1));

    let doctor = Eid::from_name("DoctC").expect("fixed Aku program EID is valid");
    assert!(
        survey.observed_program_states.contains(&(doctor, 1)),
        "Aku must enter the collected/following state after the restart"
    );
    let warp = Eid::from_name("WarpC").expect("fixed retail WarpC EID is valid");
    for state in 0..=4 {
        assert!(
            survey.observed_program_states.contains(&(warp, state)),
            "WarpC state {state} must execute before Level Complete"
        );
    }
    let ordinary_pad_bits = PAD_UP | PAD_DOWN | PAD_LEFT | PAD_RIGHT | PAD_CROSS | PAD_SQUARE;
    assert!(
        survey
            .pad_change_samples
            .iter()
            .all(|(_, held)| held & !ordinary_pad_bits == 0),
        "the route must use only ordinary directional, jump, and spin input"
    );

    assert_eq!(runtime.global_word(CHECKPOINT_ID_GLOBAL), Ok(46 << 8));
    assert_eq!(runtime.global_word(BOX_COUNT_GLOBAL), Ok(0xc00));
    let final_camera = survey
        .final_camera
        .expect("Jungle Rollers end warp must retain a camera location");
    assert_eq!(
        final_camera.path,
        RetailPathId {
            zone: Eid::from_name("0O_cZ").expect("fixed Jungle end-warp EID is valid"),
            index: 0,
        }
    );
    assert_eq!(final_camera.progress.raw(), 17_836);
    assert_eq!(
        survey.final_player_translation,
        Some([2_193_152, 7_732_266, -2_147_072])
    );
    let player = player_trace(&runtime)
        .expect("Jungle Rollers completion player trace must resolve")
        .expect("WarpC must retain Crash through its transition request");
    assert_eq!(player.state, 32);
    assert_eq!(runtime.machine().random_seed(), 0xc035_2869);
    assert_eq!(runtime.draw_count(), 3_189);
    assert_eq!(survey.unexpected_spawn_errors, 0);
    assert_eq!(survey.execution_errors, 0);
    assert_eq!(survey.faulted_objects, 0);
    assert!(
        survey.is_clean(),
        "Jungle Rollers death/Aku completion route must remain clean: {}",
        survey.summary()
    );

    let mut host = NsfProgramHost::new(&nsd, &nsf, &nsf_bytes);
    let report = runtime
        .finish_level_transition(
            &mut host,
            i32::try_from(LevelId::LEVEL_COMPLETE.get()).unwrap(),
        )
        .expect("Jungle Rollers LEVEL_END must resolve Level Complete");
    assert!(
        report.event_failures.is_empty(),
        "Jungle Rollers LEVEL_END handlers must finish cleanly: {:?}",
        report.event_failures
    );
    assert_eq!(report.resolved.level, LevelId::LEVEL_COMPLETE);
    assert!(!report.resolved.bonus_return);
    assert_eq!(report.carry.random_seed, 0xc035_2869);
    assert_eq!(report.carry.draw_count, 3_189);
}

