#[test]
#[ignore = "set C1_STREAM_DIR to legally local extracted retail streams"]
fn cortex_power_direct_boot_reaches_authored_end_warp() {
    let root = PathBuf::from(
        std::env::var_os("C1_STREAM_DIR")
            .expect("C1_STREAM_DIR must name legally local extracted retail streams"),
    );
    let level = LevelId::new_const(0x03);
    let known = KNOWN_LEVELS
        .iter()
        .find(|known| known.id == level)
        .expect("the retail level catalog contains Cortex Power");
    let (nsd, nsf, nsf_bytes) =
        parse_local_pair(&root, level).expect("the legally local Cortex Power pair must parse");
    let (survey, runtime) = survey_pair_with_runtime(
        known.name,
        level,
        &nsd,
        &nsf,
        &nsf_bytes,
        RetailRuntime::new_for_level(GLOBAL_WORDS, level),
        LevelContextSource::FreshBoot,
        SurveyInputProfile::CortexPowerCompletionRoute,
        2_400,
    )
    .expect("Cortex Power's ordinary-pad completion route must execute");

    assert_eq!(survey.frames, 2_199, "{}", survey.summary());
    assert_eq!(survey.next_lid, Some((2_199, 0x2d)));
    assert_eq!(
        survey.terminal.as_deref(),
        Some("frame 2199 requested level transition to 0x2d")
    );
    assert_eq!(survey.restarts, 0, "{}", survey.summary());
    assert!(survey.restart_frames.is_empty());
    assert_eq!(survey.death_camera_frames, 0);
    assert!(survey.first_below_zero.is_none());
    assert!(survey.first_terminal_fall.is_none());
    assert_eq!(survey.zone_transitions, 21);
    assert_eq!(survey.effect_counts.get("save-state"), Some(&1));
    assert_eq!(survey.effect_counts.get("transition"), Some(&1));
    assert_eq!(survey.unexpected_spawn_errors, 0);
    assert_eq!(survey.execution_errors, 0);
    assert_eq!(survey.faulted_objects, 0);

    let ordinary_pad_mask = PAD_UP | PAD_RIGHT | PAD_DOWN | PAD_LEFT | PAD_CROSS | PAD_SQUARE;
    assert_eq!(survey.pad_change_samples.first(), Some(&(1, PAD_RIGHT)));
    assert!(
        survey
            .pad_change_samples
            .iter()
            .all(|(_, held)| held & !ordinary_pad_mask == 0),
        "the route must use only ordinary directional, jump, and spin input"
    );

    let warp = Eid::from_name("WarpC").expect("fixed retail WarpC EID is valid");
    for state in 0..=4 {
        assert!(
            survey.observed_program_states.contains(&(warp, state)),
            "WarpC state {state} must execute before the authored transition"
        );
    }
    let player = player_trace(&runtime)
        .expect("Cortex Power completion player trace must resolve")
        .expect("WarpC must retain Crash through the transition request");
    assert_eq!(player.state, 32);
    assert_eq!(player.event, 0x1600);
    assert_eq!(runtime.draw_count(), 2_199);
    assert!(
        survey.is_clean(),
        "Cortex Power end-warp route must remain clean: {}",
        survey.summary()
    );
}

#[test]
#[ignore = "temporary legally-local Generator Room carried-phase census"]
fn temporary_generator_room_carried_phase_census() {
    let root = PathBuf::from(
        std::env::var_os("C1_STREAM_DIR")
            .expect("C1_STREAM_DIR must name legally local extracted retail streams"),
    );
    let title = CampaignPair::parse(&root, LevelId::TITLE);
    let generator_room = CampaignPair::parse(&root, LevelId::new_const(0x05));

    for (case, random_seed, draw_count, random_seed_b) in [
        ("phase-zero", 0x1357_9bdf, 0, 0),
        ("phase-a", 0x1357_9bdf, 12_345, 0x2468_ace0),
        ("phase-minus-one", 0x1357_9bdf, 12_344, 0),
        ("alternate-clock", 0xdead_beef, 50_000, 0xa5a5_5a5a),
    ] {
        let post_cortex_title =
            synthetic_title_map_carry(19, 20, random_seed, draw_count, random_seed_b);
        let generator_carry = carry_map_to_next_level(
            &title,
            post_cortex_title,
            generator_room.level,
            [0, 15, 15, 20, 1, 20, 1],
        );
        let (survey, runtime) = generator_room.run_carried(
            generator_carry,
            SurveyInputProfile::GeneratorRoomCompletionRoute,
            4_200,
        );
        eprintln!(
            "{case}: draw-start={draw_count} frames={} next-lid={:?} restarts={:?} final={:?} progression={:?}",
            survey.frames,
            survey.next_lid,
            survey.restart_frames,
            survey.final_player_translation,
            campaign_progression_globals(&runtime),
        );
    }
}

#[test]
#[ignore = "set C1_STREAM_DIR to legally local extracted retail streams"]
fn generator_room_actual_post_sunset_phase_reaches_authored_end_warp() {
    let root = PathBuf::from(
        std::env::var_os("C1_STREAM_DIR")
            .expect("C1_STREAM_DIR must name legally local extracted retail streams"),
    );
    let level = LevelId::new_const(0x05);
    let (nsd, nsf, nsf_bytes) =
        parse_local_pair(&root, level).expect("the legally local Generator Room pair must parse");

    // Exact clocks carried into Generator Room after the post-Sunset fixture
    // completes Cortex Power and traverses both retail Title boundaries.
    // Keeping them in a focused fixture preserves the inherited machinery
    // phase without replaying the whole late campaign for each route change.
    let mut title_runtime = RetailRuntime::new_for_level(GLOBAL_WORDS, LevelId::TITLE);
    for (index, value) in [
        (GAME_STATE_GLOBAL, 0),
        (TITLE_STATE_GLOBAL, 15),
        (SAVED_TITLE_STATE_GLOBAL, 15),
        (CURRENT_MAP_LEVEL_GLOBAL, 20),
        (LEVEL_COUNT_GLOBAL, 1),
        (LEVELS_UNLOCKED_GLOBAL, 20),
        (ISLAND_CAMERA_STATE_GLOBAL, 1),
    ] {
        title_runtime
            .set_global_word(index, value)
            .expect("actual post-Sunset Generator progression global is writable");
    }
    let mut carry = title_runtime.export_session_carry();
    carry.random_seed = ACTUAL_POST_SUNSET_GENERATOR_RANDOM_SEED;
    carry.draw_count = ACTUAL_POST_SUNSET_GENERATOR_DRAW_COUNT;
    carry.set_random_seed_b(ACTUAL_POST_SUNSET_GENERATOR_RANDOM_SEED_B);
    let runtime = RetailRuntime::new_from_session(GLOBAL_WORDS, level, carry)
        .expect("Generator Room must import the actual post-Sunset campaign phase");
    let (survey, runtime) = survey_pair_with_runtime(
        "Generator Room actual post-Sunset campaign phase",
        level,
        &nsd,
        &nsf,
        &nsf_bytes,
        runtime,
        LevelContextSource::SessionGlobals,
        SurveyInputProfile::GeneratorRoomCompletionRoute,
        5_500,
    )
    .expect("Generator Room's actual post-Sunset route must execute");
    let summary = survey.summary();

    assert_eq!(survey.next_lid, Some((survey.frames, 0x2d)), "{summary}");
    assert_no_campaign_recovery(&survey, "Generator Room actual post-Sunset phase");
    assert!(survey.first_terminal_fall.is_none(), "{summary}");
    assert_ordinary_completion_input(&survey, "Generator Room actual post-Sunset phase");
    assert_eq!(
        campaign_progression_globals(&runtime),
        [0x500, 15, 15, 20, 1, 21, 0],
        "{summary}"
    );
    assert!(survey.is_clean(), "{summary}");
}

#[test]
#[ignore = "set C1_STREAM_DIR to legally local extracted retail streams"]
fn generator_room_direct_boot_reaches_authored_end_warp() {
    let root = PathBuf::from(
        std::env::var_os("C1_STREAM_DIR")
            .expect("C1_STREAM_DIR must name legally local extracted retail streams"),
    );
    let level = LevelId::new_const(0x05);
    let known = KNOWN_LEVELS
        .iter()
        .find(|known| known.id == level)
        .expect("the retail level catalog contains Generator Room");
    let (nsd, nsf, nsf_bytes) =
        parse_local_pair(&root, level).expect("the legally local Generator Room pair must parse");
    let (survey, runtime) = survey_pair_with_runtime(
        known.name,
        level,
        &nsd,
        &nsf,
        &nsf_bytes,
        RetailRuntime::new_for_level(GLOBAL_WORDS, level),
        LevelContextSource::FreshBoot,
        SurveyInputProfile::GeneratorRoomCompletionRoute,
        3_600,
    )
    .expect("Generator Room's ordinary-pad completion route must execute");

    assert_eq!(survey.frames, 3_228, "{}", survey.summary());
    assert_eq!(survey.next_lid, Some((3_228, 0x2d)));
    assert_eq!(
        survey.terminal.as_deref(),
        Some("frame 3228 requested level transition to 0x2d")
    );
    assert_eq!(survey.restarts, 0, "{}", survey.summary());
    assert!(survey.restart_frames.is_empty());
    assert_eq!(survey.death_camera_frames, 0);
    assert_eq!(survey.death_camera_pose_changes, 0);
    assert_eq!(survey.death_camera_max_count, 0);
    assert!(survey.first_death_camera_pose.is_none());
    assert!(survey.last_death_camera_pose.is_none());
    assert_eq!(
        survey.first_below_zero.as_ref().map(|(frame, _)| *frame),
        Some(277),
        "negative Y is an authored part of Generator Room, not a death"
    );
    assert!(survey.first_terminal_fall.is_none());

    assert_eq!(survey.zone_transitions, 24);
    assert_eq!(survey.camera_ranges.len(), 41);
    assert_eq!(survey.camera_path_changes, 42);
    assert_eq!(survey.last_camera_path_change, 3_013);
    assert_eq!(survey.last_camera_progress_change, 3_127);
    let initial_camera = survey
        .initial_camera
        .expect("Generator Room must retain its opening camera path");
    assert_eq!(
        initial_camera.path,
        RetailPathId {
            zone: Eid::from_name("a1_5Z")
                .expect("fixed Generator Room opening camera EID is valid"),
            index: 0,
        }
    );
    assert_eq!(initial_camera.progress.raw(), 256);
    let final_camera = survey
        .final_camera
        .expect("Generator Room must retain its final camera path");
    assert_eq!(
        final_camera.path,
        RetailPathId {
            zone: Eid::from_name("c3_5Z").expect("fixed Generator Room end camera EID is valid"),
            index: 0,
        }
    );
    assert_eq!(final_camera.progress.raw(), 46_079);

    assert_eq!(survey.successful_spawns, 133);
    assert_eq!(survey.spawn_attempts, 48_229);
    assert_eq!(survey.expected_spawn_rejections, 48_096);
    assert_eq!(survey.unexpected_spawn_errors, 0);
    assert_eq!(survey.executions, 79_916);
    assert_eq!(survey.execution_errors, 0);
    assert_eq!(survey.final_live_objects, 20);
    assert_eq!(survey.max_live_objects, 50);
    assert_eq!(survey.faulted_objects, 0);
    assert!(survey.issue_counts.is_empty(), "{}", survey.summary());
    assert!(survey.first_issue.is_none());
    assert!(survey.fault_contexts.is_empty());

    assert_eq!(
        survey.checkpoint_samples,
        [
            (1, -1, [0, 0, 0]),
            (1_926, 0x5a00, [1_227_520, -1_024_512, -7_987_968]),
        ]
    );
    assert_eq!(
        survey.box_count_samples,
        [
            (1, 0),
            (562, 0x100),
            (640, 0x200),
            (1_113, 0x300),
            (1_395, 0x400),
            (1_926, 0x500),
            (1_997, 0x700),
            (1_998, 0x800),
            (2_013, 0x900),
        ]
    );
    assert_eq!(survey.saved_box_count_samples, [(1_926, 0x400)]);
    assert_eq!(survey.save_handshakes, 0);
    assert_eq!(survey.effect_counts.get("save-state"), Some(&1));
    assert!(!survey.effect_counts.contains_key("load-state"));
    assert_eq!(survey.effect_counts.get("master-fade-reset"), Some(&1));
    assert_eq!(survey.effect_counts.get("transition"), Some(&1));

    let ordinary_pad_mask = PAD_UP | PAD_RIGHT | PAD_DOWN | PAD_LEFT | PAD_CROSS | PAD_SQUARE;
    assert_eq!(survey.pad_change_samples.first(), Some(&(1, PAD_UP)));
    assert!(
        survey
            .pad_change_samples
            .iter()
            .all(|(_, held)| held & !ordinary_pad_mask == 0),
        "the route must use only ordinary directional, jump, and spin input"
    );
    let warp = Eid::from_name("WarpC").expect("fixed retail WarpC EID is valid");
    for state in 0..=4 {
        assert!(
            survey.observed_program_states.contains(&(warp, state)),
            "WarpC state {state} must execute before the authored transition"
        );
    }
    assert_eq!(
        survey.initial_player_translation,
        Some([818_944, 409_088, -179_200])
    );
    assert_eq!(
        survey.final_player_translation,
        Some([1_532_716, 2_697_818, -16_502_900])
    );
    assert_eq!(
        survey.player_minimum,
        Some([454_400, -1_090_649, -16_502_900])
    );
    assert_eq!(
        survey.player_maximum,
        Some([4_101_888, 2_697_818, -179_200])
    );
    assert_eq!(survey.last_player_movement, 3_224);
    let player = player_trace(&runtime)
        .expect("Generator Room completion player trace must resolve")
        .expect("WarpC must retain Crash through the transition request");
    assert_eq!(
        player.zone,
        Eid::from_name("c3_5Z").expect("fixed Generator Room end-warp EID is valid")
    );
    assert_eq!(player.state, 32);
    assert_eq!(player.event, 0x1600);
    assert_eq!(player.translation, [1_532_716, 2_697_818, -16_502_900]);
    assert_eq!(runtime.machine().random_seed(), 0x6778_1493);
    assert_eq!(runtime.draw_count(), 3_228);
    assert!(
        survey.is_clean(),
        "Generator Room end-warp route must remain clean: {}",
        survey.summary()
    );
}

