#[test]
#[ignore = "set C1_DISC_IMAGE to a legally local NTSC-U raw BIN"]
fn raw_bin_extraction_matches_every_local_pair_and_bootable_graph() {
    let disc_path = PathBuf::from(
        std::env::var_os("C1_DISC_IMAGE")
            .expect("C1_DISC_IMAGE must name a legally local NTSC-U raw BIN"),
    );
    let disc_bytes = std::fs::read(&disc_path)
        .unwrap_or_else(|error| panic!("{}: {error}", disc_path.display()));
    let disc = DiscImage::open(&disc_bytes)
        .unwrap_or_else(|error| panic!("{}: {error}", disc_path.display()));
    assert_eq!(disc.layout(), SectorLayout::RawMode2_2352);
    let streams = disc
        .discover_streams()
        .unwrap_or_else(|error| panic!("{}: {error}", disc_path.display()));
    streams.validate_complete_retail().unwrap();
    assert_eq!(streams.files().len(), 88);
    assert_eq!(streams.complete_pair_count(), 44);
    let extracted_root = std::env::var_os("C1_STREAM_DIR").map(PathBuf::from);
    let mut extracted_bytes = 0_u64;

    for known in KNOWN_LEVELS {
        let nsd_name = StreamName::new(known.id, StreamKind::Nsd);
        let nsf_name = StreamName::new(known.id, StreamKind::Nsf);
        let nsd_bytes = disc
            .read_stream(streams.get(nsd_name).expect("validated NSD is present"))
            .unwrap();
        let nsf_bytes = disc
            .read_stream(streams.get(nsf_name).expect("validated NSF is present"))
            .unwrap();
        extracted_bytes = extracted_bytes
            .checked_add(u64::try_from(nsd_bytes.len()).unwrap())
            .and_then(|total| total.checked_add(u64::try_from(nsf_bytes.len()).unwrap()))
            .expect("retail extraction byte count fits u64");
        if let Some(root) = &extracted_root {
            assert_eq!(
                nsd_bytes,
                std::fs::read(root.join(nsd_name.filename())).unwrap(),
                "raw-disc NSD extraction differs for {} ({})",
                known.name,
                known.id
            );
            assert_eq!(
                nsf_bytes,
                std::fs::read(root.join(nsf_name.filename())).unwrap(),
                "raw-disc NSF extraction differs for {} ({})",
                known.name,
                known.id
            );
        }
        let nsd = parse_nsd(&nsd_bytes, known.id).unwrap();
        let nsf = parse_nsf(&nsf_bytes, &nsd).unwrap();
        if known.bootable {
            graph_for_pair(known.id, &nsd, &nsf, &nsf_bytes).unwrap();
        } else {
            assert_eq!(known.id, LevelId::CAVE);
            assert!(nsd.ldat().is_none(), "Cave must remain index-only");
        }
    }
    eprintln!(
        "raw BIN {} yielded 88 exact streams across 44 pairs ({} bytes)",
        disc_path.display(),
        extracted_bytes
    );
}

#[test]
#[ignore = "set C1_DISC_IMAGE to a legally local NTSC-U raw BIN"]
fn great_gate_yellow_gem_card_route_reaches_authored_end_warp() {
    const YELLOW_GEM_BIT: u32 = 1 << 29;
    const ROUTE_FRAME_BUDGET: u32 = 3_400;

    let disc_path = PathBuf::from(
        std::env::var_os("C1_DISC_IMAGE")
            .expect("C1_DISC_IMAGE must name a legally local NTSC-U raw BIN"),
    );
    let disc_bytes = std::fs::read(&disc_path)
        .unwrap_or_else(|error| panic!("{}: {error}", disc_path.display()));
    let disc = DiscImage::open(&disc_bytes)
        .unwrap_or_else(|error| panic!("{}: {error}", disc_path.display()));
    assert_eq!(disc.layout(), SectorLayout::RawMode2_2352);
    let streams = disc.discover_streams().expect("disc streams must parse");
    streams.validate_complete_retail().unwrap();

    let level = LevelId::new_const(0x12);
    let nsd_bytes = disc
        .read_stream(
            streams
                .get(StreamName::new(level, StreamKind::Nsd))
                .expect("Great Gate NSD is present"),
        )
        .expect("Great Gate NSD is readable");
    let nsf_bytes = disc
        .read_stream(
            streams
                .get(StreamName::new(level, StreamKind::Nsf))
                .expect("Great Gate NSF is present"),
        )
        .expect("Great Gate NSF is readable");
    let nsd = parse_nsd(&nsd_bytes, level).expect("Great Gate NSD must parse");
    let nsf = parse_nsf(&nsf_bytes, &nsd).expect("Great Gate NSF must parse");
    let save = SaveData {
        level_count: 1,
        initial_lives: 4 << 8,
        sfx_volume: 255,
        music_volume: 255,
        item_pool_1: YELLOW_GEM_BIT,
        gem_count: 1,
        ..SaveData::default()
    };
    let payload = CardPayload::encode(save);
    assert!(payload.is_valid());
    assert_eq!(&payload.as_bytes()[28..32], &YELLOW_GEM_BIT.to_le_bytes());
    let loaded = payload.decode().expect("retail card payload must decode");
    assert_eq!(loaded, save);

    let mut title_runtime = RetailRuntime::new_for_level(GLOBAL_WORDS, LevelId::TITLE);
    title_runtime
        .restore_card_save_data(loaded)
        .expect("Yellow Gem progression must restore through the card path");
    for (index, value) in [
        (GAME_STATE_GLOBAL, 0),
        (TITLE_STATE_GLOBAL, TitleScreen::Map.raw()),
        (SAVED_TITLE_STATE_GLOBAL, TitleScreen::Map.raw()),
        (CURRENT_MAP_LEVEL_GLOBAL, 3),
        (LEVELS_UNLOCKED_GLOBAL, 3),
        (ISLAND_CAMERA_STATE_GLOBAL, 1),
    ] {
        title_runtime
            .set_global_word(index, value)
            .expect("pre-Great-Gate map global must exist");
    }
    assert_eq!(
        [
            LEVEL_COUNT_GLOBAL,
            ITEM_POOL_1_GLOBAL,
            ITEM_POOL_2_GLOBAL,
            GEM_COUNT_GLOBAL,
        ]
        .map(|index| title_runtime.global_word(index).unwrap()),
        [1, YELLOW_GEM_BIT, 0, 1]
    );

    // This is the exact post-Jungle Title Map phase characterized by the
    // vertical-flow test. Only the legally local card entitlement differs.
    let mut carry = title_runtime.export_session_carry();
    carry.random_seed = 0xd78d_b5d1;
    carry.draw_count = 6_065;
    let runtime = RetailRuntime::new_from_session(GLOBAL_WORDS, level, carry)
        .expect("Great Gate must import the card-backed map carry");
    let (survey, runtime) = survey_pair_with_runtime(
        "The Great Gate Yellow Gem route",
        level,
        &nsd,
        &nsf,
        &nsf_bytes,
        runtime,
        LevelContextSource::SessionGlobals,
        SurveyInputProfile::GreatGateYellowGemExactCarry,
        ROUTE_FRAME_BUDGET,
    )
    .expect("Great Gate Yellow Gem route must reach the authored end warp");
    let c8_path = RetailPathId {
        zone: Eid::from_name("c8_iZ").expect("fixed Great Gate route EID is valid"),
        index: 0,
    };
    assert_eq!(
        survey.camera_ranges.get(&c8_path),
        Some(&CameraProgressRange {
            first_frame: 2_749,
            last_frame: 3_009,
            minimum: 89,
            maximum: 21_407,
        })
    );
    assert_eq!(
        survey.camera_ranges.get(&RetailPathId {
            zone: c8_path.zone,
            index: 1,
        }),
        Some(&CameraProgressRange {
            first_frame: 2_791,
            last_frame: 2_962,
            minimum: 160,
            maximum: 15_453,
        })
    );
    let c9_path = RetailPathId {
        zone: Eid::from_name("c9_iZ").expect("fixed Great Gate route EID is valid"),
        index: 0,
    };
    assert_eq!(
        survey.camera_ranges.get(&c9_path),
        Some(&CameraProgressRange {
            first_frame: 2_864,
            last_frame: 2_901,
            minimum: 116,
            maximum: 6_122,
        })
    );
    let final_camera = survey
        .final_camera
        .expect("Yellow Gem end warp must retain its camera location");
    assert_eq!(
        final_camera.path,
        RetailPathId {
            zone: Eid::from_name("c7_iZ").expect("fixed Great Gate route EID is valid"),
            index: 0,
        }
    );
    assert_eq!(final_camera.progress.raw(), 5_292);
    assert_eq!(
        survey.final_player_translation,
        Some([3_483_392, -4_780_681, 132_864])
    );
    assert_eq!(survey.frames, 3_210);
    assert_eq!(
        survey.next_lid,
        Some((3_210, i32::try_from(LevelId::LEVEL_COMPLETE.get()).unwrap()))
    );
    assert_eq!(
        survey.terminal.as_deref(),
        Some("frame 3210 requested level transition to 0x2d")
    );
    assert_eq!(survey.restarts, 0);
    assert!(survey.restart_frames.is_empty());
    assert_eq!(survey.death_camera_frames, 0);
    assert!(survey.first_terminal_fall.is_none());
    assert_eq!(survey.effect_counts.get("transition"), Some(&1));
    assert_eq!(survey.faulted_objects, 0);
    assert_eq!(survey.execution_errors, 0);
    assert!(survey.is_clean(), "{}", survey.summary());
    assert!(
        survey.observed_program_states.contains(&(
            Eid::from_name("GemsC").expect("fixed gem-platform EID is valid"),
            2,
        )),
        "card-backed Yellow Gem must activate subtype-five GemsC platforms"
    );
    let waloc = Eid::from_name("WalOC").expect("fixed rotating-log EID is valid");
    assert!(
        survey.observed_program_states.contains(&(waloc, 2)),
        "the alternate route must flip both wall logs before climbing"
    );
    let warp = Eid::from_name("WarpC").expect("fixed retail WarpC EID is valid");
    let crash = Eid::from_name("WillC").expect("fixed player EID is valid");
    assert!(survey.observed_program_states.contains(&(warp, 1)));
    assert!(survey.observed_program_states.contains(&(crash, 32)));
    let player = player_trace(&runtime)
        .expect("Yellow Gem completion player trace must resolve")
        .expect("WarpC must retain Crash through the transition request");
    assert_eq!(player.state, 32);
    assert_eq!(player.translation, [3_483_392, -4_780_681, 132_864]);
    assert_eq!(runtime.global_word(ITEM_POOL_1_GLOBAL), Ok(YELLOW_GEM_BIT));
    assert_eq!(runtime.global_word(ITEM_POOL_2_GLOBAL), Ok(0));
    assert_eq!(runtime.global_word(GEM_COUNT_GLOBAL), Ok(1));
}

#[test]
#[ignore = "set C1_STREAM_DIR to legally local extracted retail streams"]
fn rolling_stones_carry_traverses_brio_bonus_with_ordinary_pad_input() {
    let root = PathBuf::from(
        std::env::var_os("C1_STREAM_DIR")
            .expect("C1_STREAM_DIR must name legally local extracted retail streams"),
    );
    let parent = LevelId::new_const(0x15);
    let bonus = LevelId::new_const(0x25);
    let known_name = |level| {
        KNOWN_LEVELS
            .iter()
            .find(|known| known.id == level)
            .map(|known| known.name)
            .expect("the Brio route level is present in the retail catalog")
    };

    let (parent_nsd, parent_nsf, parent_nsf_bytes) =
        parse_local_pair(&root, parent).expect("Rolling Stones pair must parse");
    let (parent_survey, mut parent_runtime) = survey_pair_with_runtime(
        known_name(parent),
        parent,
        &parent_nsd,
        &parent_nsf,
        &parent_nsf_bytes,
        RetailRuntime::new_for_level(GLOBAL_WORDS, parent),
        LevelContextSource::FreshBoot,
        SurveyInputProfile::RollingStonesBrioBonus,
        5_000,
    )
    .expect("ordinary pad input must earn Rolling Stones' complete Brio carry");
    assert_eq!(
        parent_survey.next_lid.map(|(_, lid)| lid),
        Some(i32::try_from(bonus.get()).expect("Brio Bonus LID fits i32")),
        "{}",
        parent_survey.summary()
    );
    assert_eq!(parent_survey.restarts, 0, "{}", parent_survey.summary());
    assert!(
        parent_survey.is_clean(),
        "Rolling Stones' authentic token route must remain clean: {}",
        parent_survey.summary()
    );
    assert_eq!(
        parent_runtime.global_word(60),
        Ok(14),
        "the complete Brio token carry must select Rolling Stones' authored bonus layout"
    );
    let exact_parent_snapshot = parent_runtime
        .saved_level_state()
        .cloned()
        .expect("Rolling Stones must retain its complete parent snapshot");
    let parent_transition = {
        let mut host = NsfProgramHost::new(&parent_nsd, &parent_nsf, &parent_nsf_bytes);
        parent_runtime
            .finish_level_transition(
                &mut host,
                i32::try_from(bonus.get()).expect("Brio Bonus LID fits i32"),
            )
            .expect("Rolling Stones LEVEL_END must preserve the Brio Bonus target")
    };
    assert!(parent_transition.event_failures.is_empty());
    assert_eq!(parent_transition.resolved.level, bonus);
    assert!(!parent_transition.resolved.bonus_return);
    assert_eq!(
        parent_transition.carry.saved_level_state.as_ref(),
        Some(&exact_parent_snapshot)
    );

    let (bonus_nsd, bonus_nsf, bonus_nsf_bytes) =
        parse_local_pair(&root, bonus).expect("Brio Bonus pair must parse");
    let bonus_runtime =
        RetailRuntime::new_from_session(GLOBAL_WORDS, bonus, parent_transition.carry)
            .expect("Brio Bonus must import Rolling Stones' session carry");
    assert_eq!(bonus_runtime.global_word(60), Ok(14));
    assert_eq!(
        bonus_runtime.saved_level_state(),
        Some(&exact_parent_snapshot)
    );
    let (bonus_survey, mut bonus_runtime) = survey_pair_with_runtime(
        known_name(bonus),
        bonus,
        &bonus_nsd,
        &bonus_nsf,
        &bonus_nsf_bytes,
        bonus_runtime,
        LevelContextSource::SessionGlobals,
        SurveyInputProfile::BrioBonusCompletionRoute,
        1_500,
    )
    .expect("ordinary pad input must traverse Brio Bonus");
    eprintln!("{}", bonus_survey.summary());
    assert_eq!(bonus_survey.restarts, 0, "{}", bonus_survey.summary());
    assert!(bonus_survey.restart_frames.is_empty());
    assert_eq!(bonus_survey.effect_counts.get("load-state"), Some(&1));
    assert_eq!(bonus_survey.effect_counts.get("transition"), None);
    assert_eq!(bonus_survey.next_lid, None);
    assert_eq!(
        bonus_survey.terminal.as_deref(),
        Some("requested cross-level restart from 0x25 to 0x15")
    );
    assert!(
        bonus_survey.observed_player_states.contains(&32),
        "the physical route must enter WillC's authored WARP state"
    );
    let warp = Eid::from_name("WarpC").expect("fixed retail WarpC EID is valid");
    let crash = Eid::from_name("WillC").expect("fixed retail player EID is valid");
    let warp_event = bonus_survey
        .direct_send_program_samples
        .iter()
        .find(|sample| {
            sample.event == 22 << 8
                && sample.sender == Some(warp)
                && sample.recipient == Some(crash)
        })
        .expect("the physical route must make WarpC send WillC the authored WARP event");
    assert!(
        warp_event.frame < bonus_survey.frames,
        "WarpC's event must precede the completed bonus return"
    );
    let ordinary_pad_mask = PAD_LEFT | PAD_RIGHT | PAD_UP | PAD_DOWN | PAD_CROSS | PAD_SQUARE;
    assert!(
        bonus_survey
            .pad_change_samples
            .iter()
            .all(|(_, held)| held & !ordinary_pad_mask == 0),
        "the physical Brio Bonus route must use ordinary player input only"
    );
    assert!(bonus_survey.first_terminal_fall.is_none());
    assert!(bonus_survey.is_clean(), "{}", bonus_survey.summary());
    assert_eq!(
        bonus_runtime.saved_level_state(),
        Some(&exact_parent_snapshot)
    );

    let mut bonus_host = NsfProgramHost::new(&bonus_nsd, &bonus_nsf, &bonus_nsf_bytes);
    let return_transition = bonus_runtime
        .finish_level_transition(&mut bonus_host, -2)
        .expect("the bonus LEVEL_END phase must resolve the carried Rolling Stones snapshot");
    assert!(return_transition.event_failures.is_empty());
    assert_eq!(return_transition.next_lid_after_event, -2);
    assert_eq!(return_transition.resolved.level, parent);
    assert!(return_transition.resolved.bonus_return);
    assert_eq!(
        return_transition.carry.saved_level_state.as_ref(),
        Some(&exact_parent_snapshot)
    );
}

#[test]
#[ignore = "set C1_STREAM_DIR to legally local extracted retail streams"]
fn great_hall_all_gems_route_reaches_authored_epilogue_and_title() {
    // Exact retail completion inventory: 18 clear-gem and six colored-gem
    // flags live in pool one; the remaining two clear gems and both keys live
    // in pool two. Do not grant unrelated/unused item bits to reach the
    // authored 100% branch.
    const ALL_GEMS_POOL_1: u32 = 0x2fbd_f7be;
    const ALL_GEMS_AND_KEYS_POOL_2: u32 = 0x0014_0500;

    let root = PathBuf::from(
        std::env::var_os("C1_STREAM_DIR")
            .expect("C1_STREAM_DIR must name legally local extracted retail streams"),
    );
    let level = LevelId::new_const(0x2c);
    let (nsd, nsf, nsf_bytes) =
        parse_local_pair(&root, level).expect("The Great Hall pair must parse");
    let (title_nsd, title_nsf, title_nsf_bytes) =
        parse_local_pair(&root, LevelId::TITLE).expect("The Title pair must parse");
    let save = SaveData {
        level_count: 30,
        gem_count: 26,
        key_count: 2,
        item_pool_1: ALL_GEMS_POOL_1,
        item_pool_2: ALL_GEMS_AND_KEYS_POOL_2,
        initial_lives: 4 << 8,
        sfx_volume: 255,
        music_volume: 255,
        ..SaveData::default()
    };
    let title_runtime =
        authored_completed_card_load_runtime(&title_nsd, &title_nsf, &title_nsf_bytes, save);
    let mut map = AuthoredTitleMapHarness::from_runtime(
        &title_nsd,
        &title_nsf,
        &title_nsf_bytes,
        title_runtime,
    );
    map.wait_until_ready(64);
    for _ in 0..120 {
        map.step(0);
    }
    map.step(PAD_CROSS);
    assert_eq!(map.transitions, [(131, 0x2c)]);
    let carry = {
        let mut host = NsfProgramHost::new(&title_nsd, &title_nsf, &title_nsf_bytes);
        map.runtime
            .finish_level_transition(&mut host, 0x2c)
            .expect("Title Map exports its Great Hall carry")
            .carry
    };
    let runtime = RetailRuntime::new_from_session(GLOBAL_WORDS, level, carry)
        .expect("The Great Hall imports the completed-card carry");
    let (survey, mut runtime) = survey_pair_with_runtime(
        "The Great Hall all-gems branch",
        level,
        &nsd,
        &nsf,
        &nsf_bytes,
        runtime,
        LevelContextSource::SessionGlobals,
        SurveyInputProfile::GreatHallAllGemsRoute,
        8_000,
    )
    .expect("The Great Hall all-gems route executes");

    assert_eq!(survey.frames, 6_944, "{}", survey.summary());
    assert_eq!(survey.next_lid, Some((6_944, 0x19)));
    assert_eq!(
        survey.terminal.as_deref(),
        Some("frame 6944 requested level transition to 0x19")
    );
    assert_eq!(survey.effect_counts.get("transition"), Some(&1));
    assert_eq!(survey.effect_counts.get("spawn-children"), Some(&195));
    assert!(!survey.effect_counts.contains_key("load-state"));
    assert_eq!(survey.restarts, 0);
    assert!(survey.restart_frames.is_empty());
    assert_eq!(survey.death_camera_frames, 0);
    assert!(survey.first_below_zero.is_none());
    assert!(survey.first_terminal_fall.is_none());
    assert_eq!(survey.faulted_objects, 0);
    assert_eq!(survey.execution_errors, 0);
    assert_eq!(survey.unexpected_spawn_errors, 0);
    assert!(survey.is_clean(), "{}", survey.summary());

    let path_first_frame = |zone: &str, index| {
        let path = RetailPathId {
            zone: Eid::from_name(zone).expect("fixed Great Hall route EID is valid"),
            index,
        };
        survey
            .camera_ranges
            .get(&path)
            .unwrap_or_else(|| panic!("Great Hall route must visit {path:?}: {}", survey.summary()))
            .first_frame
    };
    assert_eq!(path_first_frame("a7_IZ", 0), 928);
    assert_eq!(path_first_frame("a8_IZ", 0), 1_028);
    assert_eq!(path_first_frame("x__IZ", 0), 1_122);
    assert_eq!(path_first_frame("y__IZ", 0), 1_722);
    assert_eq!(path_first_frame("x__IZ", 2), 4_149);
    assert_eq!(survey.camera_ranges.len(), 24);
    assert_eq!(survey.camera_path_changes, 23);
    assert_eq!(survey.last_camera_path_change, 4_149);
    assert_eq!(survey.zone_transitions, 11);
    assert_eq!(survey.max_live_objects, 91);
    assert_eq!(survey.successful_spawns, 25);
    assert_eq!(survey.executions, 226_612);
    assert_eq!(
        survey.final_camera,
        Some(RetailCameraLocation {
            path: RetailPathId {
                zone: Eid::from_name("x__IZ").expect("fixed Great Hall epilogue EID is valid"),
                index: 2,
            },
            progress: PathProgress::ZERO,
        })
    );

    let win = Eid::from_name("WinGC").expect("fixed Great Hall ending-controller EID is valid");
    for state in [0, 2, 3, 5, 6, 7, 8, 9, 10, 35] {
        assert!(
            survey.observed_program_states.contains(&(win, state)),
            "the authored WinGC epilogue must execute state {state}: {}",
            survey.summary()
        );
    }
    assert!(
        survey.spawn_child_kinds.contains(&(61, 3)),
        "WinGC must synchronously spawn its subtype-three dynamic epilogue text"
    );
    let shadow = Eid::from_name("ShadC").expect("fixed retail shadow EID is valid");
    assert!(survey.observed_program_states.contains(&(shadow, 1)));

    let ordinary_pad_mask = PAD_LEFT | PAD_RIGHT | PAD_UP | PAD_DOWN | PAD_CROSS | PAD_SQUARE;
    assert!(
        survey
            .pad_change_samples
            .iter()
            .all(|(_, held)| held & !ordinary_pad_mask == 0)
    );
    assert_eq!(
        survey.final_player_translation,
        Some([8_279_948, 1_031_154, 24_872_448])
    );
    let player = player_trace(&runtime)
        .expect("Great Hall epilogue player trace must resolve")
        .expect("Great Hall must retain Crash through the transition request");
    assert_eq!(player.state, 33);
    assert_eq!(player.translation, [8_279_948, 1_031_154, 24_872_448]);
    assert_eq!(runtime.global_word(GEM_COUNT_GLOBAL), Ok(26));
    assert_eq!(runtime.global_word(ITEM_POOL_1_GLOBAL), Ok(ALL_GEMS_POOL_1));
    assert_eq!(
        runtime.global_word(ITEM_POOL_2_GLOBAL),
        Ok(ALL_GEMS_AND_KEYS_POOL_2)
    );

    let mut host = NsfProgramHost::new(&nsd, &nsf, &nsf_bytes);
    let transition = runtime
        .finish_level_transition(&mut host, 0x19)
        .expect("Great Hall epilogue LEVEL_END must export its Title carry");
    assert!(transition.event_failures.is_empty());
    assert_eq!(transition.resolved.level, LevelId::TITLE);
    assert!(!transition.resolved.bonus_return);
}
